audit.entries:
.input {$count :number}
.match $count
one {{{$count} entry verified for this tenant.}}
* {{{$count} entries verified for this tenant.}}

companies.audit_broken:
.input {$count :number}
.match $count
one {{{$count} broken audit log}}
* {{{$count} broken audit logs}}

operator.summary:
.input {$count :number}
.match $count
one {{{$count} invoice, {$total} excl. VAT. For the operator tenant, these are the subscription invoices issued as Factur-X.}}
* {{{$count} invoices, {$total} excl. VAT. For the operator tenant, these are the subscription invoices issued as Factur-X.}}

users.total:
.input {$count :number}
.match $count
one {{{$count} account in total.}}
* {{{$count} accounts in total.}}
